CREATE OR REPLACE FUNCTION public.complete_production_plan(p_requester_id bigint, p_plan_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_user_location_id bigint;
  v_plan_location_id bigint;
begin

  -- Sprawdzamy pracownika
  select role, location_id
  into v_role, v_user_location_id
  from public."Employees"
  where id = p_requester_id
    and active = true;

  if not found then
    raise exception 'Brak dostępu';
  end if;

  -- Employee nie może kończyć całego planu
  if v_role not in ('administrator', 'manager', 'su-chef') then
    raise exception 'Nie masz uprawnień do zakończenia planu';
  end if;

  -- Sprawdzamy lokal planu
  select location_id
  into v_plan_location_id
  from public."Plans"
  where id = p_plan_id
    and status = 'active';

  if not found then
    raise exception 'Nie znaleziono aktywnego planu';
  end if;

  -- Manager i su-chef tylko w swoim lokalu
  if v_role <> 'administrator'
     and v_user_location_id <> v_plan_location_id then
    raise exception 'Nie masz uprawnień do tego lokalu';
  end if;

  -- Kończymy plan
  update public."Plans"
  set status = 'completed'
  where id = p_plan_id;

end;
$function$

CREATE OR REPLACE FUNCTION public.delete_plan_item(p_requester_id bigint, p_item_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_user_location_id bigint;

  v_plan_location_id bigint;
  v_started_at timestamptz;
  v_gotowe boolean;
BEGIN

  -- Kto wykonuje operację?
  SELECT
    e.role,
    e.location_id
  INTO
    v_role,
    v_user_location_id
  FROM public."Employees" e
  WHERE e.id = p_requester_id
    AND e.active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Brak dostępu';
  END IF;

  -- Tylko administrator, manager i su-chef
  IF v_role NOT IN ('administrator', 'manager', 'su-chef') THEN
    RAISE EXCEPTION 'Nie masz uprawnień do usuwania pozycji';
  END IF;

  -- Pobieramy pozycję i jej plan
  SELECT
    p.location_id,
    pi.started_at,
    COALESCE(pi.gotowe, false)
  INTO
    v_plan_location_id,
    v_started_at,
    v_gotowe
  FROM public."Plan_items" pi
  JOIN public."Plans" p
    ON p.id = pi.plan_id
  WHERE pi.id = p_item_id
    AND p.status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nie znaleziono pozycji w aktywnym planie';
  END IF;

  -- Manager i su-chef tylko w swoim lokalu
  IF v_role <> 'administrator'
     AND v_user_location_id IS DISTINCT FROM v_plan_location_id THEN
    RAISE EXCEPTION 'Nie masz uprawnień do tego lokalu';
  END IF;

  -- Rozpoczętej pracy nie wolno usuwać
  IF v_started_at IS NOT NULL THEN
    RAISE EXCEPTION 'Nie można usunąć rozpoczętej pozycji';
  END IF;

  -- Gotowej pozycji tym bardziej nie usuwamy
  IF v_gotowe THEN
    RAISE EXCEPTION 'Nie można usunąć zakończonej pozycji';
  END IF;

  DELETE FROM public."Plan_items"
  WHERE id = p_item_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.start_plan_item(p_requester_id bigint, p_item_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$BEGIN
-- ZAGOTOWKI_CURRENT_DATE_GUARD_V1

  -- Dotyczy wszystkich ról. Brak lub inna data nie może uruchomić starego RPC.
  -- Blokada planu utrzymuje status/datę stabilne do końca operacji.
  PERFORM 1
  FROM public."Plans" AS date_guard_plan
  JOIN public."Plan_items" AS date_guard_item ON date_guard_item.plan_id = date_guard_plan.id
  WHERE date_guard_item.id = p_item_id
    AND date_guard_plan.plan_date = (now() AT TIME ZONE 'Europe/Warsaw')::date
  FOR UPDATE OF date_guard_plan;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operacja jest dostępna wyłącznie dla planu na dziś' USING ERRCODE = '42501';
  END IF;


DECLARE
  v_user_location_id bigint;
  v_plan_location_id bigint;
  v_item_started_at timestamptz;
  v_item_gotowe boolean;
BEGIN

  -- Sprawdzamy pracownika
  SELECT e.location_id
  INTO v_user_location_id
  FROM public."Employees" e
  WHERE e.id = p_requester_id
    AND e.active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Brak dostępu';
  END IF;

  -- Pracownik musi być przypisany do lokalu
  IF v_user_location_id IS NULL THEN
    RAISE EXCEPTION 'Pracownik nie jest przypisany do lokalu';
  END IF;

  -- Sprawdzamy pozycję + aktywny plan
  SELECT
    p.location_id,
    pi.started_at,
    COALESCE(pi.gotowe, false)
  INTO
    v_plan_location_id,
    v_item_started_at,
    v_item_gotowe
  FROM public."Plan_items" pi
  JOIN public."Plans" p
    ON p.id = pi.plan_id
  WHERE pi.id = p_item_id
    AND p.status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nie znaleziono pozycji w aktywnym planie';
  END IF;

  -- Tylko własny lokal
  IF v_user_location_id IS DISTINCT FROM v_plan_location_id THEN
    RAISE EXCEPTION 'Nie masz uprawnień do tego lokalu';
  END IF;

  -- Nie uruchamiamy ponownie zakończonego zadania
  IF v_item_gotowe THEN
    RAISE EXCEPTION 'Ta pozycja jest już zakończona';
  END IF;

  -- Nie resetujemy czasu przez ponowne kliknięcie
  IF v_item_started_at IS NOT NULL THEN
    RAISE EXCEPTION 'Ta pozycja jest już w trakcie pracy';
  END IF;

  UPDATE public."Plan_items"
  SET
    started_at = now(),
    completed_at = NULL,
    gotowe = false
  WHERE id = p_item_id;

END;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_production_plan(p_requester_id bigint, p_plan_id bigint, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_user_location_id bigint;
  v_plan_location_id bigint;
begin

  select role, location_id
  into v_role, v_user_location_id
  from public."Employees"
  where id = p_requester_id
    and active = true;

  if not found then
    raise exception 'Brak dostępu';
  end if;

  if v_role not in ('administrator', 'manager', 'su-chef') then
    raise exception 'Nie masz uprawnień do edycji planu';
  end if;

  select location_id
  into v_plan_location_id
  from public."Plans"
  where id = p_plan_id
    and status = 'active';

  if not found then
    raise exception 'Nie znaleziono aktywnego planu';
  end if;

  if v_role <> 'administrator'
     and v_user_location_id <> v_plan_location_id then
    raise exception 'Nie masz uprawnień do tego lokalu';
  end if;

  delete from public."Plan_items"
  where plan_id = p_plan_id;

  insert into public."Plan_items" (
    plan_id,
    product_external_id,
    nazwa,
    ilosc,
    jednostka,
    priorytet,
    gotowe
  )
  select
    p_plan_id,
    x.product_external_id,
    x.nazwa,
    x.ilosc,
    x.jednostka,
    x.priorytet,
    false
  from jsonb_to_recordset(p_items) as x(
    product_external_id bigint,
    nazwa text,
    ilosc numeric,
    jednostka text,
    priorytet text
  );

end;
$function$

CREATE OR REPLACE FUNCTION public.add_plan_item(p_requester_id bigint, p_plan_id bigint, p_nazwa text, p_ilosc numeric, p_jednostka text, p_priorytet text, p_product_external_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_user_location_id bigint;
  v_plan_location_id bigint;
  v_item_id bigint;
BEGIN

  SELECT role, location_id
  INTO v_role, v_user_location_id
  FROM public."Employees"
  WHERE id = p_requester_id
    AND active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Brak dostępu';
  END IF;

  IF v_role NOT IN ('administrator', 'manager', 'su-chef') THEN
    RAISE EXCEPTION 'Nie masz uprawnień do dodawania pozycji';
  END IF;

  SELECT location_id
  INTO v_plan_location_id
  FROM public."Plans"
  WHERE id = p_plan_id
    AND status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nie znaleziono aktywnego planu';
  END IF;

  IF v_role <> 'administrator'
     AND v_user_location_id IS DISTINCT FROM v_plan_location_id THEN
    RAISE EXCEPTION 'Nie masz uprawnień do tego lokalu';
  END IF;

  IF p_nazwa IS NULL OR trim(p_nazwa) = '' THEN
    RAISE EXCEPTION 'Nazwa jest wymagana';
  END IF;

  IF p_ilosc IS NULL OR p_ilosc <= 0 THEN
    RAISE EXCEPTION 'Ilość musi być większa od 0';
  END IF;

  IF p_jednostka NOT IN ('g', 'kg', 'ml', 'l', 'szt.') THEN
    RAISE EXCEPTION 'Nieprawidłowa jednostka';
  END IF;

  IF p_priorytet NOT IN ('normalny', 'wysoki', 'pilny') THEN
    RAISE EXCEPTION 'Nieprawidłowy priorytet';
  END IF;

  INSERT INTO public."Plan_items" (
    plan_id,
    product_external_id,
    nazwa,
    ilosc,
    jednostka,
    priorytet,
    gotowe
  )
  VALUES (
    p_plan_id,
    p_product_external_id,
    trim(p_nazwa),
    p_ilosc,
    p_jednostka,
    p_priorytet,
    false
  )
  RETURNING id INTO v_item_id;

  RETURN v_item_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.update_plan_item(p_requester_id bigint, p_item_id bigint, p_nazwa text, p_ilosc numeric, p_jednostka text, p_priorytet text, p_product_external_id bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_user_location_id bigint;
  v_plan_location_id bigint;
  v_started_at timestamptz;
  v_gotowe boolean;
BEGIN

  SELECT e.role, e.location_id
  INTO v_role, v_user_location_id
  FROM public."Employees" e
  WHERE e.id = p_requester_id
    AND e.active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Brak dostępu';
  END IF;

  IF v_role NOT IN ('administrator', 'manager', 'su-chef') THEN
    RAISE EXCEPTION 'Nie masz uprawnień do edycji pozycji';
  END IF;

  SELECT
    p.location_id,
    pi.started_at,
    COALESCE(pi.gotowe, false)
  INTO
    v_plan_location_id,
    v_started_at,
    v_gotowe
  FROM public."Plan_items" pi
  JOIN public."Plans" p
    ON p.id = pi.plan_id
  WHERE pi.id = p_item_id
    AND p.status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nie znaleziono pozycji w aktywnym planie';
  END IF;

  IF v_role <> 'administrator'
     AND v_user_location_id IS DISTINCT FROM v_plan_location_id THEN
    RAISE EXCEPTION 'Nie masz uprawnień do tego lokalu';
  END IF;

  IF v_started_at IS NOT NULL OR v_gotowe THEN
    RAISE EXCEPTION 'Nie można edytować rozpoczętej pozycji';
  END IF;

  IF p_nazwa IS NULL OR trim(p_nazwa) = '' THEN
    RAISE EXCEPTION 'Nazwa jest wymagana';
  END IF;

  IF p_ilosc IS NULL OR p_ilosc <= 0 THEN
    RAISE EXCEPTION 'Ilość musi być większa od 0';
  END IF;

  IF p_jednostka NOT IN ('g', 'kg', 'ml', 'l', 'szt.') THEN
    RAISE EXCEPTION 'Nieprawidłowa jednostka';
  END IF;

  IF p_priorytet NOT IN ('normalny', 'wysoki', 'pilny') THEN
    RAISE EXCEPTION 'Nieprawidłowy priorytet';
  END IF;

  UPDATE public."Plan_items"
  SET
    product_external_id = p_product_external_id,
    nazwa = trim(p_nazwa),
    ilosc = p_ilosc,
    jednostka = p_jednostka,
    priorytet = p_priorytet
  WHERE id = p_item_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.reopen_production_plan(p_requester_id bigint, p_plan_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  requester public."Employees"%ROWTYPE;
  target_plan public."Plans"%ROWTYPE;
BEGIN
  SELECT * INTO requester FROM public."Employees"
    WHERE id = p_requester_id AND active = true
    FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nieaktywny lub nieistniejący pracownik' USING ERRCODE = '42501';
  END IF;
  IF requester.role IS NULL OR requester.role NOT IN ('administrator', 'manager', 'su-chef') THEN
    RAISE EXCEPTION 'Brak uprawnień do wznowienia planu' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO target_plan FROM public."Plans" WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan nie istnieje' USING ERRCODE = 'P0002';
  END IF;
  IF requester.role <> 'administrator' AND
    (requester.location_id IS NULL OR requester.location_id IS DISTINCT FROM target_plan.location_id) THEN
    RAISE EXCEPTION 'Brak uprawnień do tego lokalu' USING ERRCODE = '42501';
  END IF;
  IF target_plan.status IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION 'Wznowić można wyłącznie zakończony plan' USING ERRCODE = '55000';
  END IF;

  UPDATE public."Plans" SET status = 'active' WHERE id = p_plan_id;
  -- Żadnych operacji na Plan_items ani innych polach Plans.
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_plan_item(p_requester_id bigint, p_item_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$BEGIN
-- ZAGOTOWKI_CURRENT_DATE_GUARD_V1

  -- Dotyczy wszystkich ról. Brak lub inna data nie może uruchomić starego RPC.
  -- Blokada planu utrzymuje status/datę stabilne do końca operacji.
  PERFORM 1
  FROM public."Plans" AS date_guard_plan
  JOIN public."Plan_items" AS date_guard_item ON date_guard_item.plan_id = date_guard_plan.id
  WHERE date_guard_item.id = p_item_id
    AND date_guard_plan.plan_date = (now() AT TIME ZONE 'Europe/Warsaw')::date
  FOR UPDATE OF date_guard_plan;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operacja jest dostępna wyłącznie dla planu na dziś' USING ERRCODE = '42501';
  END IF;


DECLARE
  v_user_location_id bigint;
  v_plan_location_id bigint;
  v_item_started_at timestamptz;
  v_item_gotowe boolean;
BEGIN

  -- Sprawdzamy pracownika
  SELECT e.location_id
  INTO v_user_location_id
  FROM public."Employees" e
  WHERE e.id = p_requester_id
    AND e.active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Brak dostępu';
  END IF;

  IF v_user_location_id IS NULL THEN
    RAISE EXCEPTION 'Pracownik nie jest przypisany do lokalu';
  END IF;

  -- Sprawdzamy pozycję + aktywny plan
  SELECT
    p.location_id,
    pi.started_at,
    COALESCE(pi.gotowe, false)
  INTO
    v_plan_location_id,
    v_item_started_at,
    v_item_gotowe
  FROM public."Plan_items" pi
  JOIN public."Plans" p
    ON p.id = pi.plan_id
  WHERE pi.id = p_item_id
    AND p.status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nie znaleziono pozycji w aktywnym planie';
  END IF;

  -- Tylko własny lokal
  IF v_user_location_id IS DISTINCT FROM v_plan_location_id THEN
    RAISE EXCEPTION 'Nie masz uprawnień do tego lokalu';
  END IF;

  -- Musi być wcześniej rozpoczęta
  IF v_item_started_at IS NULL THEN
    RAISE EXCEPTION 'Najpierw rozpocznij pracę';
  END IF;

  IF v_item_gotowe THEN
    RAISE EXCEPTION 'Ta pozycja jest już zakończona';
  END IF;

  -- WAŻNE:
  -- employee_id pochodzi z requester_id.
  -- Frontend nie może wskazać innego pracownika.
  UPDATE public."Plan_items"
  SET
    gotowe = true,
    completed_at = now(),
    employee_id = p_requester_id
  WHERE id = p_item_id;

END;
END;
$function$
